433:func (s *Store) listDeploymentIdentityProviders() []*storepb.IdentityProvider {
434:	s.deploymentConfigMu.RLock()
435:	defer s.deploymentConfigMu.RUnlock()
436:	providers := make([]*storepb.IdentityProvider, 0, len(s.deploymentConfig.identityProviders))
437:	for _, provider := range s.deploymentConfig.identityProviders {
438:		providers = append(providers, cloneIdentityProvider(provider))
439:	}
440:	slices.SortFunc(providers, func(a, b *storepb.IdentityProvider) int { return strings.Compare(a.Uid, b.Uid) })
441:	return providers
